R="/home/user/https-ivan-petrov.github.io-grani-mirov-/";H="/tmp/claude-0/-home-user-https-ivan-petrov-github-io-grani-mirov-/27f5cebc-2d4b-556f-9c1f-bc733d69f26b/scratchpad/hron/"
def patch(path,pairs,need=True):
    s=open(path,encoding="utf-8").read();n=0
    for a,b in pairs:
        if a in s:s=s.replace(a,b);n+=1
        elif need and b not in s:raise SystemExit(f"{path}: нет «{a[:60]}»")
    open(path,"w",encoding="utf-8").write(s);print(path.split("/")[-1],"правок",n)
